// Generated by tour2playwright from a Tour Recorder export, then hand-edited.
// Source tour: Finance: Reconcile Journal Items ( Customer Invoice and Payment ) - Full Flow
// Hand edits: the invoice/payment pair is found by RPC (the recorded pair is used up once reconciled), text-based
// selectors, state assertions, result screenshots, wide viewport, login fallback.
// WRITES (test database only): reconciles one open customer invoice line with one payment line of the same partner.
// A reconciliation cannot be undone by this test, so each run consumes one pair.
import { test, expect } from "../../../../core/fixtures/index";
import type { Page, Locator } from "@playwright/test";
import fs from "node:fs";

const SHOT_DIR = "tools/tour2playwright/generated/screenshots/finance-reconcile-journal-items-customer-invoice-and-payment-full-flow";

// A step's own screenshot is taken BEFORE its action; this keeps one of the finished screen.
async function resultShot(page: Page, n: number) {
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/step-${String(n).padStart(2, "0")}-result.png` });
}

// Screenshot the current page with the target element outlined.
async function shot(page: Page, loc: Locator, file: string) {
  try {
    await loc.scrollIntoViewIfNeeded({ timeout: 5000 });
    await loc.evaluate((el) => el.setAttribute("data-t2p", "1"));
    await page.addStyleTag({
      content: '[data-t2p="1"]{outline:3px solid #e01e5a !important;outline-offset:2px !important;}',
    });
  } catch {}
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/${file}` });
  try { await loc.evaluate((el) => el.removeAttribute("data-t2p")); } catch {}
}

type Line = { id: number; partner_id: [number, string]; account_id: [number, string]; company_id: [number, string]; move_name: string; amount_residual: number };

test.describe("Finance: Reconcile Journal Items ( Customer Invoice and Payment ) - Full Flow @module:accounting @step:business @e2e", () => {
  // At the default 1280px some top-menu entries collapse into the "+" overflow.
  test.use({ viewport: { width: 1600, height: 900 } });

  test("Finance: Reconcile Journal Items ( Customer Invoice and Payment ) - Full Flow", async ({ page, rpc }) => {
    test.skip(
      process.env.TOUR_ALLOW_WRITES !== "true",
      "Reconciles a real invoice with a real payment (irreversible here) — set TOUR_ALLOW_WRITES=true to run",
    );
    test.setTimeout(240_000);

    // ------------------------------------------------------------------ data: one open invoice line + one payment line of the same partner and account
    const lines = await rpc.searchRead<Line>(
      "account.move.line",
      [["reconciled", "=", false], ["account_id.account_type", "=", "asset_receivable"], ["parent_state", "=", "posted"], ["partner_id", "!=", false]],
      ["partner_id", "account_id", "company_id", "move_name", "amount_residual"], { limit: 5000, order: "id desc" });
    const groups = new Map<string, Line[]>();
    for (const l of lines) {
      const k = `${l.partner_id[0]}|${l.account_id[0]}`;
      groups.set(k, [...(groups.get(k) ?? []), l]);
    }
    let pair: { inv: Line; pay: Line; size: number } | undefined;
    for (const ls of groups.values()) {
      for (const inv of ls.filter((x) => x.amount_residual > 0)) {
        const pay = ls.find((x) => x.amount_residual < 0 && Math.abs(x.amount_residual + inv.amount_residual) < 0.005);
        // Prefer the smallest group, so the screenshots are short and the pair is easy to see.
        if (pay && (!pair || ls.length < pair.size)) pair = { inv, pay, size: ls.length };
      }
    }
    expect(pair, "an open invoice and an equal payment for the same customer must exist").toBeTruthy();
    const { inv, pay } = pair!;

    // Records of this company are only visible when the session is on that company.
    await page.context().addCookies([{ name: "cids", value: String(inv.company_id[0]), url: process.env.ODOO_BASE_URL ?? "http://localhost:8069" }]);
    await page.goto("/web");
    // The rpc fixture's API login can end the saved browser session — fall back to the login form.
    const emailBox = page.getByRole("textbox", { name: "Email" });
    if (await emailBox.isVisible({ timeout: 8_000 }).catch(() => false)) {
      await emailBox.fill(process.env.ADMIN_EMAIL ?? "admin");
      await page.getByRole("textbox", { name: "Password" }).fill(process.env.ADMIN_PASSWORD ?? "admin");
      await page.getByRole("button", { name: "Log in" }).click();
      await page.waitForSelector(".o_main_navbar, .o_home_menu", { state: "visible", timeout: 45_000 });
    }
    await page.waitForLoadState("networkidle", { timeout: 10_000 }).catch(() => {});
    // The tour starts INSIDE the Accounting app, but /web lands on the app picker.
    const app = page.getByRole("option", { name: "Accounting", exact: true });
    if (await app.isVisible({ timeout: 10_000 }).catch(() => false)) await app.click();
    await expect(page.locator(".o_menu_sections")).toBeVisible({ timeout: 45000 });

    const run = async (n: number, title: string, loc: Locator, act?: (l: Locator) => Promise<void>, result = false) => {
      await test.step(`${String(n).padStart(2, "0")}. ${title}`, async () => {
        const l = loc.first();
        await l.waitFor({ state: "visible", timeout: 45000 });
        await shot(page, l, `step-${String(n).padStart(2, "0")}.png`);
        if (act) await act(l);
        if (result) await resultShot(page, n);
      });
    };
    const topMenu = (name: string) => page.locator(".o_menu_sections .dropdown-toggle, .o_menu_sections > a").filter({ hasText: new RegExp(`^${name}$`) });
    const header = (text: string | RegExp) => page.locator("tr.o_group_header").filter({ hasText: text });
    const accountCode = inv.account_id[1].split(" ")[0];
    const rowFor = (move: string) => page.locator("tr.o_data_row").filter({ hasText: move });
    const isReconciled = async (id: number) =>
      (await rpc.searchRead<{ reconciled: boolean }>("account.move.line", [["id", "=", id]], ["reconciled"], { limit: 1 }))[0]?.reconciled === true;

    await run(1, "Open the Accounting menu", topMenu("Accounting"), async (l) => {
      await l.click();
      await expect(page.locator('[data-menu-xmlid="account_accountant.menu_account_reconcile"]').first()).toBeVisible({ timeout: 15000 });
    }, true);
    await run(2, "Click Reconcile under Actions", page.locator('[data-menu-xmlid="account_accountant.menu_account_reconcile"]'), async (l) => {
      await l.click();
      await expect(page.locator(".o_list_view"), "Reconcile list opened").toBeVisible({ timeout: 45000 });
    }, true);
    await run(3, "Check the Unreconciled filter", page.locator(".o_searchview_facet").filter({ hasText: /Unreconciled/ }), async (l) => {
      await expect(l).toBeVisible();
    });
    await run(4, "Expand the customer group", header(accountCode), async (l) => {
      // Odoo remembers which groups are open: only click when the account group is still closed.
      if (!(await l.evaluate((el) => el.classList.contains("o_group_open")))) await l.click();
      // The partner group that sits directly under THIS account (other accounts have a group for the same partner too).
      const partner = header(accountCode).first().locator("xpath=following-sibling::tr[contains(@class,'o_group_header')][1]");
      await expect(partner, "partner group under the account").toContainText(inv.partner_id[1], { timeout: 20000 });
      await shot(page, partner, "step-04.png");
      if (!(await partner.evaluate((el) => el.classList.contains("o_group_open")))) await partner.click();
      await expect(rowFor(inv.move_name).first(), "journal items of the partner").toBeVisible({ timeout: 20000 });
    }, true);
    await run(5, "Select the payment line", rowFor(pay.move_name).locator(".o-checkbox input, input[type=checkbox]"), async (l) => {
      await l.check();
      await expect(l).toBeChecked();
    }, true);
    await run(6, "Select the invoice line", rowFor(inv.move_name).locator(".o-checkbox input, input[type=checkbox]"), async (l) => {
      await l.check();
      await expect(l).toBeChecked();
    }, true);
    await run(7, "Click the Reconcile button", page.locator('button[name="action_reconcile"]'), async (l) => {
      await l.click();
      // Odoo applies the reconciliation a moment after the click — wait for it, and never click twice.
      await expect.poll(() => isReconciled(inv.id), { timeout: 45000, message: "invoice line should be reconciled" }).toBe(true);
      await expect.poll(() => isReconciled(pay.id), { timeout: 45000, message: "payment line should be reconciled" }).toBe(true);
    }, true);
    await run(8, "Confirm the lines are matched", page.locator(".o_list_view, .o_view_nocontent").first(), async (l) => {
      await expect(rowFor(inv.move_name), "the invoice left the unreconciled list").toHaveCount(0, { timeout: 20000 });
    });
    await run(9, "Remove the Unreconciled filter", page.locator(".o_searchview_facet").filter({ hasText: /Unreconciled/ }).locator(".o_facet_remove"), async (l) => {
      await l.click();
      await expect(page.locator(".o_searchview_facet").filter({ hasText: /Unreconciled/ })).toHaveCount(0, { timeout: 15000 });
    }, true);
  });
});
